package com.mediqueue.dto;

import jakarta.validation.ConstraintViolation;
import jakarta.validation.ConstraintViolationException;
import jakarta.validation.Validator;
import java.util.Set;
import java.util.stream.Collectors;

/**
 * Accounts created by the administrator use the same {@link RegisterRequest} as patient sign-up,
 * but the password is generated by the server, so any password sent is ignored and not validated.
 */
public final class AdminAccountRequests {

    private AdminAccountRequests() {}

    public static void validate(Validator validator, RegisterRequest request) {
        request.setPassword(null);
        Set<ConstraintViolation<RegisterRequest>> violations =
                validator.validate(request).stream()
                        .filter(v -> !"password".equals(v.getPropertyPath().toString()))
                        .collect(Collectors.toSet());
        if (!violations.isEmpty()) throw new ConstraintViolationException(violations);
    }
}
